local k={209,97,83,206,162,58,7,214,208,86,97,202,154,109,211,12,168,53,204,155,101,101,74,168,185,234,25,71,98,167,124,135}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
